<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>2048</title>
<style>
  * { box-sizing: border-box; }
  body {
    margin: 0;
    min-height: 100vh;
    background: #121212;
    color: #f5f5f5;
    font-family: Arial, Helvetica, sans-serif;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: flex-start;
    padding: 24px 16px;
  }
  h1 { margin: 0 0 12px 0; font-size: 48px; letter-spacing: 2px; }
  .hud {
    display: flex;
    align-items: center;
    gap: 16px;
    margin-bottom: 16px;
  }
  .score-box {
    background: #1e1e1e;
    border: 1px solid #333;
    border-radius: 8px;
    padding: 8px 18px;
    text-align: center;
    font-size: 14px;
    color: #aaa;
    text-transform: uppercase;
  }
  #score {
    display: block;
    font-size: 24px;
    font-weight: bold;
    color: #fff;
  }
  #reset {
    background: #f65e3b;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 12px 18px;
    font-size: 16px;
    font-weight: bold;
    cursor: pointer;
  }
  #reset:hover { background: #e04e2d; }
  #board {
    width: min(90vw, 440px);
    aspect-ratio: 1 / 1;
    background: #1e1e1e;
    border-radius: 12px;
    padding: 10px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(4, 1fr);
    gap: 10px;
  }
  .tile {
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 8px;
    font-size: clamp(20px, 6vw, 32px);
    font-weight: bold;
    background: #2c2c2c;
    color: #fff;
    min-height: 0;
    user-select: none;
  }
  .tile.empty { background: #2a2a2a; color: transparent; }
  .tile.v2 { background: #3a3a3a; }
  .tile.v4 { background: #4a4a52; }
  .tile.v8 { background: #f2b179; color: #fff; }
  .tile.v16 { background: #f59563; }
  .tile.v32 { background: #f67c5f; }
  .tile.v64 { background: #f65e3b; }
  .tile.v128 { background: #edcf72; color: #333; }
  .tile.v256 { background: #edcc61; color: #333; }
  .tile.v512 { background: #edc850; color: #333; }
  .tile.v1024 { background: #edc53f; color: #333; }
  .tile.v2048 { background: #edc22e; color: #333; }
  .hint { margin-top: 14px; color: #888; font-size: 14px; }
</style>
</head>
<body>
<h1>2048</h1>
<div class="hud">
  <div class="score-box">Score<span id="score">0</span></div>
  <button id="reset">New Game</button>
</div>
<div id="board"></div>
<div class="hint">Use arrow keys to play</div>
<script>
(function() {
  var SIZE = 4;
  var grid = [];
  var scoreVal = 0;
  var boardEl = document.getElementById('board');
  var scoreEl = document.getElementById('score');
  var resetBtn = document.getElementById('reset');

  function emptyGrid() {
    var g = [];
    for (var r = 0; r < SIZE; r++) {
      g.push([0, 0, 0, 0]);
    }
    return g;
  }

  function updateScore() {
    scoreEl.textContent = String(scoreVal);
  }

  function render() {
    boardEl.innerHTML = '';
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = grid[r] ? grid[r][c] : 0;
        var d = document.createElement('div');
        d.className = 'tile' + (v === 0 ? ' empty' : ' v' + v);
        d.textContent = v === 0 ? '' : String(v);
        d.setAttribute('data-r', r);
        d.setAttribute('data-c', c);
        boardEl.appendChild(d);
      }
    }
    updateScore();
  }

  function spawnOne() {
    var empties = [];
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        if (grid[r][c] === 0) empties.push([r, c]);
      }
    }
    if (empties.length === 0) return false;
    var pick = empties[Math.floor(Math.random() * empties.length)];
    grid[pick[0]][pick[1]] = Math.random() < 0.9 ? 2 : 4;
    return true;
  }

  function slideAndMergeLeft(line) {
    var filtered = line.filter(function(v) { return v !== 0; });
    var merged = [];
    var gained = 0;
    var i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        var m = filtered[i] * 2;
        merged.push(m);
        gained += m;
        i += 2;
      } else {
        merged.push(filtered[i]);
        i += 1;
      }
    }
    while (merged.length < SIZE) merged.push(0);
    return { line: merged, gained: gained };
  }

  function move(dir) {
    if (dir !== 'left' && dir !== 'right' && dir !== 'up' && dir !== 'down') return false;
    var newGrid = emptyGrid();
    var gainedTotal = 0;
    var r, c;

    if (dir === 'left') {
      for (r = 0; r < SIZE; r++) {
        var resL = slideAndMergeLeft(grid[r].slice());
        newGrid[r] = resL.line;
        gainedTotal += resL.gained;
      }
    } else if (dir === 'right') {
      for (r = 0; r < SIZE; r++) {
        var rev = grid[r].slice().reverse();
        var resR = slideAndMergeLeft(rev);
        newGrid[r] = resR.line.reverse();
        gainedTotal += resR.gained;
      }
    } else if (dir === 'up') {
      for (c = 0; c < SIZE; c++) {
        var col = [];
        for (r = 0; r < SIZE; r++) col.push(grid[r][c]);
        var resU = slideAndMergeLeft(col);
        for (r = 0; r < SIZE; r++) newGrid[r][c] = resU.line[r];
        gainedTotal += resU.gained;
      }
    } else if (dir === 'down') {
      for (c = 0; c < SIZE; c++) {
        var col2 = [];
        for (r = 0; r < SIZE; r++) col2.push(grid[r][c]);
        col2 = col2.reverse();
        var resD = slideAndMergeLeft(col2);
        var restored = resD.line.reverse();
        for (r = 0; r < SIZE; r++) newGrid[r][c] = restored[r];
        gainedTotal += resD.gained;
      }
    }

    var moved = false;
    for (r = 0; r < SIZE; r++) {
      for (c = 0; c < SIZE; c++) {
        if (grid[r][c] !== newGrid[r][c]) { moved = true; break; }
      }
      if (moved) break;
    }

    if (!moved) return false;

    grid = newGrid;
    scoreVal += gainedTotal;
    spawnOne();
    render();
    return true;
  }

  function reset() {
    grid = emptyGrid();
    scoreVal = 0;
    spawnOne();
    spawnOne();
    render();
  }

  function board() {
    return grid.map(function(row) { return row.slice(); });
  }

  function setBoard(arr) {
    grid = emptyGrid();
    for (var r = 0; r < SIZE; r++) {
      for (var c = 0; c < SIZE; c++) {
        var v = (arr && arr[r] && typeof arr[r][c] === 'number') ? arr[r][c] : 0;
        grid[r][c] = v;
      }
    }
    scoreVal = 0;
    render();
  }

  function score() {
    return scoreVal;
  }

  window.game = {
    size: SIZE,
    reset: reset,
    move: move,
    board: board,
    setBoard: setBoard,
    score: score
  };

  resetBtn.addEventListener('click', function() { reset(); });

  document.addEventListener('keydown', function(e) {
    var dir = null;
    if (e.key === 'ArrowLeft') dir = 'left';
    else if (e.key === 'ArrowRight') dir = 'right';
    else if (e.key === 'ArrowUp') dir = 'up';
    else if (e.key === 'ArrowDown') dir = 'down';
    if (dir) {
      e.preventDefault();
      move(dir);
    }
  });

  reset();
})();
</script>
</body>
</html>
